import { useEffect, useState } from "react";
import axios from "axios";
import AdminPanel from "./components/AdminPanel";
import AuthPage from "./components/Authpage";

const API_URL = "http://localhost:5000";

function App() {
  const [candidates, setCandidates] = useState([]);
  const [darkMode, setDarkMode] = useState(false);
  const [auth, setAuth] = useState({
    token: localStorage.getItem("token") || null,
    role: localStorage.getItem("role") || null,
  });

  const [candidateForm, setCandidateForm] = useState({
    firstName: "",
    lastName: "",
    candidacy: "",
    description: "",
    image: null,
  });

  const [editId, setEditId] = useState(null);
  const [message, setMessage] = useState("");
  const [votedPositions, setVotedPositions] = useState([]);

  // =======================
  // API Calls
  // =======================
  const fetchCandidates = async () => {
    try {
      const res = await axios.get(`${API_URL}/api/candidates`);
      setCandidates(res.data);
    } catch (error) {
      console.error(error);
      setMessage("Failed to load candidates.");
    }
  };

  const fetchUserVotes = async (token) => {
    try {
      const res = await axios.get(`${API_URL}/api/auth/votes`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setVotedPositions(res.data);
    } catch (error) {
      console.error(error);
    }
  };

  useEffect(() => {
    fetchCandidates();
    if (auth.token) fetchUserVotes(auth.token);
  }, [auth.token]);

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("role");
    setAuth({ token: null, role: null });
    setVotedPositions([]);
  };

  const handleVote = async (id, position) => {
    try {
      const res = await axios.post(
        `${API_URL}/api/vote/${id}`,
        {},
        { headers: { Authorization: `Bearer ${auth.token}` } }
      );

      setMessage(res.data.message);
      setVotedPositions((prev) => [...prev, position]);

      setCandidates((prev) =>
        prev.map((c) =>
          c._id === id ? { ...c, votes: (c.votes || 0) + 1 } : c
        )
      );
    } catch (error) {
      setMessage(error.response?.data?.message || "Voting failed.");
    }
  };

  const handleSaveCandidate = async () => {
    try {
      const formData = new FormData();
      formData.append("firstName", candidateForm.firstName);
      formData.append("lastName", candidateForm.lastName);
      formData.append("candidacy", candidateForm.candidacy);
      formData.append("description", candidateForm.description || "");
      if (candidateForm.image) formData.append("image", candidateForm.image);

      if (editId) {
        await axios.put(`${API_URL}/api/candidates/${editId}`, formData, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });
        setMessage("Candidate updated.");
      } else {
        await axios.post(`${API_URL}/api/candidates`, formData, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });
        setMessage("Candidate added.");
      }

      setCandidateForm({
        firstName: "",
        lastName: "",
        candidacy: "",
        description: "",
        image: null,
      });
      setEditId(null);
      fetchCandidates();
    } catch (error) {
      setMessage("Failed to save candidate.");
    }
  };

  const handleDeleteCandidate = async (id) => {
    try {
      await axios.delete(`${API_URL}/api/candidates/${id}`, {
        headers: { Authorization: `Bearer ${auth.token}` },
      });
      setMessage("Candidate deleted.");
      fetchCandidates();
    } catch (error) {
      setMessage("Delete failed.");
    }
  };

  const groupedCandidates = candidates.reduce((acc, candidate) => {
    const key = candidate.candidacy || "Other";
    if (!acc[key]) acc[key] = [];
    acc[key].push(candidate);
    return acc;
  }, {});

  const theme = {
    text: darkMode ? "#e5e7eb" : "#000",
    cardBackground: darkMode ? "#1f2937" : "#fff",
    cardShadow: darkMode
      ? "0 4px 12px rgba(0,0,0,0.5)"
      : "0 4px 12px rgba(0,0,0,0.15)",
    button: "#1e40af",
  };

  if (!auth.token) {
    return <AuthPage setAuth={setAuth} />;
  }

  return (
    <div
      style={{
        minHeight: "100vh",
        width: "100%",
        padding: 20,
        color: theme.text,
        boxSizing: "border-box",
        background: darkMode
          ? "linear-gradient(135deg, #0f2027, #203a43, #2c5364)"
          : "linear-gradient(135deg, #ffecd2, #fcb69f)",
        transition: "background 0.5s ease",
      }}
    >
      <h1 style={{ textAlign: "center", marginBottom: 20 }}>
        Online Voting System
      </h1>

      <div style={{ marginBottom: 20, textAlign: "center" }}>
        <button
          onClick={() => setDarkMode(!darkMode)}
          style={{
            padding: "8px 16px",
            border: "none",
            borderRadius: 5,
            cursor: "pointer",
            transition: "transform 0.2s",
          }}
          onMouseEnter={(e) => (e.currentTarget.style.transform = "scale(1.05)")}
          onMouseLeave={(e) => (e.currentTarget.style.transform = "scale(1)")}
        >
          {darkMode ? "Light Mode" : "Dark Mode"}
        </button>

        <button
          onClick={handleLogout}
          style={{
            marginLeft: 10,
            padding: "8px 16px",
            border: "none",
            borderRadius: 5,
            cursor: "pointer",
            transition: "transform 0.2s",
          }}
          onMouseEnter={(e) => (e.currentTarget.style.transform = "scale(1.05)")}
          onMouseLeave={(e) => (e.currentTarget.style.transform = "scale(1)")}
        >
          Logout
        </button>
      </div>

      {message && (
        <p style={{ textAlign: "center", fontWeight: "bold" }}>{message}</p>
      )}

      {auth.role === "admin" && (
        <div
          style={{
            maxWidth: 600,
            margin: "0 auto 30px auto",
            background: theme.cardBackground,
            padding: 20,
            borderRadius: 12,
            boxShadow: theme.cardShadow,
            transition: "transform 0.2s, box-shadow 0.2s",
          }}
          onMouseEnter={(e) => {
            e.currentTarget.style.transform = "translateY(-5px)";
            e.currentTarget.style.boxShadow = "0 8px 20px rgba(0,0,0,0.4)";
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.transform = "translateY(0)";
            e.currentTarget.style.boxShadow = theme.cardShadow;
          }}
        >
          <AdminPanel
            candidateForm={candidateForm}
            setCandidateForm={setCandidateForm}
            onSave={handleSaveCandidate}
          />
        </div>
      )}

      <section>
        {Object.entries(groupedCandidates).map(([position, list]) => (
          <div key={position} style={{ marginBottom: 30 }}>
            <h2 style={{ marginBottom: 15 }}>{position}</h2>

            {list.map((c) => (
              <div
                key={c._id}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: 15,
                  marginBottom: 15,
                  padding: 15,
                  borderRadius: 10,
                  background: theme.cardBackground,
                  boxShadow: theme.cardShadow,
                  maxWidth: 600,
                  marginLeft: "auto",
                  marginRight: "auto",
                  transition: "transform 0.2s, box-shadow 0.2s",
                  cursor: "pointer",
                }}
                onMouseEnter={(e) => {
                  e.currentTarget.style.transform = "translateY(-5px)";
                  e.currentTarget.style.boxShadow = "0 8px 20px rgba(0,0,0,0.3)";
                }}
                onMouseLeave={(e) => {
                  e.currentTarget.style.transform = "translateY(0)";
                  e.currentTarget.style.boxShadow = theme.cardShadow;
                }}
              >
                {/* Candidate Avatar */}
                {c.image && (
                  <img
                    src={`${API_URL}/${c.image}`}
                    alt={`${c.firstName} ${c.lastName}`}
                    style={{
                      width: 60,
                      height: 60,
                      borderRadius: "50%",
                      objectFit: "cover",
                      transition: "transform 0.3s",
                    }}
                    onMouseEnter={(e) =>
                      (e.currentTarget.style.transform = "scale(1.1)")
                    }
                    onMouseLeave={(e) =>
                      (e.currentTarget.style.transform = "scale(1)")
                    }
                  />
                )}

                <div style={{ flex: 1 }}>
                  <h3>
                    {c.firstName} {c.lastName}
                  </h3>
                  <p>Votes: {c.votes || 0}</p>

                  {auth.role === "user" && (
                    <button
                      onClick={() => handleVote(c._id, c.candidacy)}
                      disabled={votedPositions.includes(c.candidacy)}
                      style={{
                        background: theme.button,
                        color: "#fff",
                        padding: "6px 12px",
                        border: "none",
                        borderRadius: 5,
                        cursor: "pointer",
                        transition: "transform 0.2s",
                        marginTop: 5,
                      }}
                      onMouseEnter={(e) =>
                        (e.currentTarget.style.transform = "scale(1.05)")
                      }
                      onMouseLeave={(e) =>
                        (e.currentTarget.style.transform = "scale(1)")
                      }
                    >
                      {votedPositions.includes(c.candidacy)
                        ? "Voted"
                        : "Vote"}
                    </button>
                  )}

                  {auth.role === "admin" && (
                    <div style={{ marginTop: 10 }}>
                      <button
                        onClick={() => {
                          setEditId(c._id);
                          setCandidateForm({
                            firstName: c.firstName,
                            lastName: c.lastName,
                            candidacy: c.candidacy,
                            description: c.description || "",
                            image: null,
                          });
                        }}
                        style={{
                          marginRight: 10,
                          padding: "6px 12px",
                          borderRadius: 5,
                          cursor: "pointer",
                          transition: "transform 0.2s",
                        }}
                        onMouseEnter={(e) =>
                          (e.currentTarget.style.transform = "scale(1.05)")
                        }
                        onMouseLeave={(e) =>
                          (e.currentTarget.style.transform = "scale(1)")
                        }
                      >
                        Edit
                      </button>

                      <button
                        onClick={() => handleDeleteCandidate(c._id)}
                        style={{
                          padding: "6px 12px",
                          borderRadius: 5,
                          cursor: "pointer",
                          transition: "transform 0.2s",
                        }}
                        onMouseEnter={(e) =>
                          (e.currentTarget.style.transform = "scale(1.05)")
                        }
                        onMouseLeave={(e) =>
                          (e.currentTarget.style.transform = "scale(1)")
                        }
                      >
                        Delete
                      </button>
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        ))}
      </section>
    </div>
  );
}

export default App;
